package com.netbanking.account.service; import com.netbanking.account.dto.response.LedgerResponse; import com.netbanking.account.repository.AccountLedgerRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class LedgerService {private final AccountService accounts;private final AccountLedgerRepository ledger;public LedgerService(AccountService a,AccountLedgerRepository l){accounts=a;ledger=l;}@Transactional(readOnly=true) public List<LedgerResponse> list(Long id){accounts.account(id);return ledger.findByAccountIdOrderByCreatedAtDesc(id).stream().map(LedgerResponse::from).toList();}}
